# Generated by build.py from recipe.yml for recipe http-prove-a-client-uses-its-proxy. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s\n' 'hello from surl' > site/hello.txt
printf '%s\n' '{"widget": 3}' > site/prices.json
cat > via-proxy.awk <<'EOF'
{ sub(/\r$/, "") }
# A request head in origin form (GET /path) is one the origin received.
/^[0-9a-f]+: [A-Z]+ \// { open = 1; via = 0; next }
open && /^[0-9a-f]+: Via: 1\.1 surl$/ { via = 1 }
# The blank line that ends the head.
open && /^[0-9a-f]+: ?$/ { if (via) proxied++; else direct++; open = 0 }
END {
  printf "%d via the proxy, %d direct\n", proxied, direct
  exit (direct > 0)
}
EOF
surl --directory site --trace-ascii traffic.txt http://127.0.0.1:8080/ --proxy http://127.0.0.1:8081/ &
sleep 1
curl -sS -x http://127.0.0.1:8081/ -o hello.txt http://127.0.0.1:8080/hello.txt -o prices.json http://127.0.0.1:8080/prices.json
awk -f via-proxy.awk traffic.txt
kill $(jobs -p)
